-- Mod-authored era splash painting descriptions, pl_PL overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Brak opisu dla tej epoki."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Wielka kolumnowa świątynia stoi najwyżej na tarasowym wzgórzu; mniejsze kolumnady opadają schodami w dół po jej prawej stronie. Ogrody wspinają się po zboczu poniżej, gdzie wąskie schody wzdłuż jasnego skalnego urwiska porosłego cyprysami i kwitnącymi krzewami. Cały marmur jarzy się ciepłym złotem w słońcu."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Złote pola pszenicy falują pod murowanym miastem bladych wież na wzgórzu. Z blanków zwisają czerwone sztandary; największy niesie czarnego ptaka z rozpostartymi skrzydłami. Trwają żniwa: zgarbieni chłopi zbierają ścięte zboże, inni niosą na plecach wysokie snopy, a robotnicy w centrum ładują wóz zaprzężony w parę ciemnych wołów. Drzewa pochylają się przy górnych narożnikach obrazu pod miękkim, zamglonym niebem."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Wysoko ponad dachami Florencji Michał Anioł stoi na drewnianej drabinie, rzeźbiąc kolosalnego białego marmurowego Dawida. Sama głowa i ramiona posągu wypełniają lewą część kadru; rzeźbiarz sięga ledwie do jego ramienia. Poniżej czerwone dachówki rozciągają się aż po wielką kopułę katedry florenckiej i smukłą dzwonnicę. Za nimi złote światło przebija się przez burzowociemne niebo."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "Czerwono-biały parowiec kołowy przecina na pierwszym planie wody portu nowojorskiego, snując dym z dwóch czarnych kominów. Pasażerowie stoją wzdłuż obu pokładów. Za nim Statua Wolności wznosi się zielona na tle mglistego bursztynowego nieba; w oddali inne statki parują po wodzie. Dym i mgła zabarwiają całą scenę ciepłą sepią i złotem."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "Patrzący wygląda z dachu jednego wieżowca na miasto pełne innych. Oświetlone wieże cofają się blok za blokiem w złotą mgłę. Daleko w dole naziemne autostrady wiją się przez rozległy węzeł, którym płyną strumienie samochodów i ciężarówek. Cały obraz utrzymany jest w jednej barwie, złotej i sepii jak odbarwione zdjęcie."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Nisko wiszące słońce płonie na dalekim końcu śródmiejskiej ulicy z połowy dwudziestego wieku, zalewając ją złotym światłem. Mężczyźni w garniturach i kapeluszach fedora idą prawym chodnikiem tyłem do patrzącego, mijając markizy i dużą literowaną markizę teatralną. Zaokrąglone ciemne sedany parkują wzdłuż krawężnika lub przejeżdżają obok. W głębi budynki roztapiają się w blasku."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Futurystyczne miasto lśni wzdłuż złotego wybrzeża, jego smukłe wieże cofają się w górę linii brzegowej w mgłę. Po lewej elegancki czerwono-biały odrzutowiec zakręca nad wodą; za nim most wiszący rozpina się nad zatoką. Na pierwszym planie po prawej kopulasty kompleks z chromu i szkła wbudowany jest w nadmorskie klify. Zieleń oblega jego tarasy; na kładce stoi samotna postać."
